import{j as e}from"./vendor-react-BlVc7RbY.js";import{P as a}from"./ProblemPage-KaPViw5X.js";import"./vendor-misc-BAGPFqjl.js";import"./index-BlrmFtr-.js";import"./vendor-ui-D7glRu94.js";import"./vendor-framer-motion-_M9ViFvP.js";import"./Breadcrumb-H_CkWXx7.js";function c(){return e.jsx(a,{slug:"isolamento-termico",pageTitle:"Isolamento Térmico Sem Obras: ClimateCoating Para Paredes e Fachadas",metaTitle:"Isolamento Térmico Sem Obras Para Casa | Evoluimos Comércio",metaDescription:"Isolamento térmico aplicado como tinta. ClimateCoating reduz perdas de calor no inverno, calor no verão e humidade do ar. Sem ETICS, sem cápotos, sem obras.",heroImage:"/ClimateCoating/baldestinta.webp",heroImageAlt:"Aplicação de ClimateCoating como tinta de isolamento térmico",introParagraph:"O isolamento térmico tradicional, ETICS ou cápoto, exige andaimes, semanas de obras e custos elevados. Existe agora uma alternativa: o ClimateCoating é um revestimento cerâmico aplicado como tinta, em qualquer parede ou fachada.",searchKeywords:["isolamento térmico","como isolar casa","isolamento sem obras","ClimateCoating","tinta isolante térmica"],problem:"As casas portuguesas perdem em média 30 a 50% da energia de aquecimento e refrigeração pela envolvente exterior, paredes, coberturas, janelas. O isolamento térmico tradicional (sistema ETICS ou cápoto) resolve o problema, mas tem custos elevados, exige andaimes, demora semanas e altera significativamente o aspecto da fachada. Para muitos proprietários, especialmente em edifícios com valor patrimonial ou em apartamentos, este caminho é inviável.",causes:[{title:"Construções antigas sem isolamento",text:"Edifícios anteriores aos anos 90 raramente têm isolamento térmico nas paredes ou na cobertura. As paredes simples têm coeficiente de transmissão térmica três a cinco vezes superior ao recomendado actualmente."},{title:"Pontes térmicas em pilares e vigas",text:"Mesmo edifícios mais recentes têm pontes térmicas em pilares, vigas e contornos de janelas. Estas zonas concentram perdas de calor e são pontos críticos de condensação interior."},{title:"Coberturas e tectos sem isolamento",text:"Telhados expostos ao sol no verão e ao frio no inverno são responsáveis por grande parte das perdas e ganhos térmicos indesejados. Pisos superiores ficam quentes no verão e frios no inverno."},{title:"Fachadas históricas que não permitem cápoto",text:"Em edifícios históricos, em centros antigos ou em condomínios com regras estéticas, o sistema ETICS é incompatível com a preservação da fachada original."}],consequences:["Consumo elevado de aquecimento no inverno, com casas frias mesmo com equipamentos potentes","Calor extremo no verão, especialmente em últimos andares e sob coberturas expostas ao sol","Condensação nas paredes interiores frias, com risco de bolores e degradação","Conforto térmico baixo, sensação de paredes frias mesmo com ar quente","Classe energética baixa, com impacto no valor do imóvel","Aquecimento e arrefecimento permanentemente ligados, com custos acumulados"],solution:"O ClimateCoating é um revestimento cerâmico de alta tecnologia, desenvolvido a partir de tecnologia aeroespacial. Composto por microesferas cerâmicas suspensas numa base de tinta, é aplicado em paredes interiores ou exteriores com rolo ou pincel, como uma pintura normal. Cria uma membrana fina (1 a 2 mm) que reflete radiação infravermelha, regula a humidade do ar e reduz pontes térmicas. Existe em três variantes principais: ThermoProtect para fachadas exteriores, ThermoPlus para interiores e InterioPlus para regulação fina do ar interior. Compatível com qualquer suporte, incluindo edifícios históricos, sem alterar a estética da fachada.",benefits:["Aplicação como tinta, sem andaimes complexos nem obras estruturais","Compatível com fachadas históricas e edifícios em reabilitação","Reduz perdas térmicas no inverno e ganhos solares no verão","Regula humidade do ar interior, anti-condensação","Garantia superior a 15 anos, com durabilidade comprovada acima de 20 anos","Autolimpante e impermeável, sem necessidade de repintura frequente"],process:[{title:"Diagnóstico térmico",text:"Visita técnica com avaliação de pontes térmicas, humidade e estado da fachada. Identificamos as zonas prioritárias de aplicação."},{title:"Preparação da superfície",text:"Limpeza, tratamento de fissuras e aplicação de primário onde necessário. A superfície fica pronta para receber o ClimateCoating."},{title:"Aplicação do ClimateCoating",text:"Aplicação em duas a três demãos com rolo ou pincel. Em moradias tipo, demora entre 2 e 5 dias. Sem demolições, sem retirar mobília."},{title:"Acabamento e validação",text:"Demão final, validação visual e térmica. Apoio técnico contínuo durante a garantia."}],faqs:[{question:"O ClimateCoating é mesmo equivalente a um cápoto tradicional?",answer:"Tem um princípio físico diferente. O cápoto adiciona uma camada espessa de material isolante (poliestireno, lã mineral) que reduz a condução térmica. O ClimateCoating atua principalmente por reflexão de radiação infravermelha e por regulação da humidade do ar. Em conjunto com tratamento da humidade, o desempenho real em conforto e em consumo é comparável, com a vantagem de não alterar a fachada."},{question:"Que poupança energética posso esperar?",answer:"Tipicamente entre 20 e 35% nas faturas de aquecimento e arrefecimento, dependendo do estado inicial do edifício, da exposição solar e do clima. Em edifícios muito mal isolados as poupanças podem ser superiores."},{question:"É possível aplicar só em algumas paredes?",answer:"Sim. Recomendamos priorizar paredes mais frias (orientadas a norte), paredes mais quentes (orientadas a oeste no verão) e tectos sob cobertura. A aplicação faseada é prática comum em apartamentos e moradias com orçamentos repartidos."},{question:"Funciona em paredes com humidade?",answer:"Antes de aplicar ClimateCoating é fundamental eliminar a humidade ascendente. O nosso processo recomenda Drymat primeiro (2 a 6 meses) e ClimateCoating depois. Se a parede tiver apenas condensação, o ClimateCoating sozinho resolve ao regular a humidade do ar para cerca de 55%."},{question:"Pode ser pintado por cima?",answer:"Sim. O ClimateCoating é compatível com pinturas decorativas posteriores, embora a textura cerâmica final seja já elegante e durável. Recomendamos manter a camada cerâmica visível."},{question:"É autorizado em edifícios classificados?",answer:"Em geral sim, porque não altera a estrutura nem a aparência da fachada. Em monumentos nacionais ou edifícios com tutela específica, verificamos sempre com as entidades competentes antes da aplicação."},{question:"Pode ser combinado com painéis solares fotovoltaicos?",answer:"Totalmente. A combinação é uma estratégia integrada de eficiência energética: ClimateCoating reduz a procura de aquecimento e arrefecimento, e os painéis solares geram a energia restante de forma renovável."},{question:"É inflamável?",answer:"Não. O ClimateCoating tem classificação de comportamento ao fogo A2 (não combustível), o que o torna adequado para edifícios residenciais, escolares, hospitais e ERP."}],relatedProducts:[{label:"ClimateCoating",path:"/products/climatecoating"},{label:"Drymat (preparação anterior)",path:"/products/drymat"}],relatedSolutions:[{label:"Reduzir custos de aquecimento",path:"/reduzir-custos-aquecimento"},{label:"Humidade nas paredes",path:"/humidade-nas-paredes"},{label:"Casa quente no verão",path:"/casa-quente-no-verao"}],serviceName:"Isolamento térmico ClimateCoating",serviceType:"Isolamento térmico cerâmico aplicado como tinta"})}export{c as default};
